/* From Uiverse.io by Admin12121 - Tags: cardgift, card template, card animation, card hover */
.__UIV_SCOPE__ .education {
  --bg-color: #ffd861;
  --bg-color-light: #ffeeba;
  --text-color-hover: #4C5656;
  --box-shadow-color: rgba(255, 215, 97, 0.48);
}

.__UIV_SCOPE__ .card {
  width: 220px;
  height: 321px;
  background: #fff;
  border-top-right-radius: 10px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  position: relative;
  box-shadow: 0 14px 26px rgba(0,0,0,0.04);
  transition: all 0.3s ease-out;
  text-decoration: none;
}

.__UIV_SCOPE__ .card:hover {
  transform: translateY(-5px) scale(1.005) translateZ(0);
  box-shadow: 0 24px 36px rgba(0,0,0,0.11),
    0 24px 46px var(--box-shadow-color);
}

.__UIV_SCOPE__ .card:hover .overlay {
  transform: scale(4) translateZ(0);
}

.__UIV_SCOPE__ .card:hover .circle {
  border-color: var(--bg-color-light);
  background: var(--bg-color);
}

.__UIV_SCOPE__ .card:hover .circle:after {
  background: var(--bg-color-light);
}

.__UIV_SCOPE__ .card:hover p {
  color: var(--text-color-hover);
}

.__UIV_SCOPE__ .card:active {
  transform: scale(1) translateZ(0);
  box-shadow: 0 15px 24px rgba(0,0,0,0.11),
    0 15px 24px var(--box-shadow-color);
}

.__UIV_SCOPE__ .card p {
  font-size: 17px;
  color: #4C5656;
  margin-top: 30px;
  z-index: 1000;
  transition: color 0.3s ease-out;
}

.__UIV_SCOPE__ .circle {
  width: 131px;
  height: 131px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--bg-color);
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  z-index: 1;
  transition: all 0.3s ease-out;
}

.__UIV_SCOPE__ .circle:after {
  content: "";
  width: 118px;
  height: 118px;
  display: block;
  position: absolute;
  background: var(--bg-color);
  border-radius: 50%;
  transition: opacity 0.3s ease-out;
}

.__UIV_SCOPE__ .circle svg {
  z-index: 10000;
  transform: translateZ(0);
}

.__UIV_SCOPE__ .overlay {
  width: 118px;
  position: absolute;
  height: 118px;
  border-radius: 50%;
  background: var(--bg-color);
  top: 70px;
  left: 50px;
  z-index: 0;
  transition: transform 0.3s ease-out;
}
